"""Reviewed promotion candidates -> selected.csv (one raw own-site page each); every quote is verified against the cached page text."""
import hashlib,json,sys
from pathlib import Path
H=Path(__file__).resolve().parent;ROOT=H.parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from site_corpus import on_page,same_page,url as norm
from prep import write
from research import CACHE
PERSIST=Path('/Users/johnswanson/.bb/thread-storage/thr_9i2c6byhcz/2026-11-06-atlas/persist/strong-wave-site-quality-2')
# site_id: (url, scope quote, activity quote, city, binding quote, context quote, note)
C={
'SITE-011167':('https://cjkpackaging.com/about/','Since 1993, CJK Manufacturing, LLC has been a supplier of custom-engineered thermoformed packaging and packaging components.','We specialize in designing and manufacturing custom packaging for retail products, but we also offer a wide range of sustainable packaging materials','Rochester','Visit CJK Packaging 160 Commerce Dr Rochester NY 14623','Forming Capabilities Thin Gauge In-Line Thermoforming/Vacuum Forming','About page names the legal operator and a first-person manufacturing statement; its only address is the filed Rochester street.'),
'SITE-011169':('https://eckplastics.com/about/','Eck Plastic Arts is located in Binghamton, NY and produces quality plastic parts for original equipment manufacturers.','Eck Plastic Arts is located in Binghamton, NY and produces quality plastic parts for original equipment manufacturers.','Binghamton','87 Prospect Avenue Binghamton, New York 13901','Injection Molding Thermoforming Plastic Fabrication Product Finishing Operations','Page brand Eck Plastic Arts is the trading name recorded in the held organization note; a same-street federal ITA row is also named ECK PLASTIC ARTS; exact filed street printed on page.'),
'SITE-011171':('https://nortekpowder.com/contact/','Nortek Powder Coating is a manufacturer of high-quality powder coatings.','Nortek Powder Coating is a manufacturer of high-quality powder coatings.','Rome','Nortek Powder Coating, LLC 5900 Success Drive, Rome, NY 13440, USA.','','Contact page prints the exact legal operator and filed street beside the manufacturer statement.'),
'SITE-011172':('https://aladdinpackaging.com/','From our corporate and manufacturing headquarters in Hauppauge, New York, we spread our magic and help sustain industries and businesses across our great nation.','We manage every process involved in getting from endless rolls of plastic to beautiful, high-quality bags, pouches, wrappers and lidding products.','Hauppauge','Hauppauge 115 Engineers Road Hauppauge, NY 11788','','Home page calls Hauppauge its manufacturing headquarters and prints the exact filed street; the separate Newburgh address is not asserted.'),
'SITE-011302':('https://www.masterbond.com/content/how-purchase-our-products','Master Bond products are manufactured and available for purchase exclusively from our location in Hackensack, NJ USA.','Master Bond products are manufactured and available for purchase exclusively from our location in Hackensack, NJ USA.','Hackensack','Master Bond Inc 154 Hobart Street Hackensack, NJ 07601 USA','Find the Right Adhesive for Your Application','Single page states manufacture at its sole Hackensack location and prints the exact legal operator and filed street.'),
'SITE-011306':('https://www.microsealindustries.com','we also manufacture and compound our own adhesives and coatings.','Our state of the art facility has over 15 different coating methods, and we also manufacture and compound our own adhesives and coatings.','Paterson','Microseal Industries Inc. 610 E 36th Street Paterson, NJ 07513','','Home page states the facility makes its own adhesives and coatings; its only printed address is the filed Paterson street.'),
'SITE-011313':('https://www.rez-cure.com/about','Innovative Resin Systems is a family-owned epoxy resin and specialty chemical manufacturer and formulator specializing in custom adhesive, coating, sealant, and encapsulation systems engineered for demanding applications.','Innovative Resin Systems is a family-owned epoxy resin and specialty chemical manufacturer and formulator specializing in custom adhesive, coating, sealant, and encapsulation systems engineered for demanding applications.','Newark','Innovative Resin Systems Where demanding applications find their formula. 257 Wilson Ave, Newark, NJ 07105','Expanded into a state-of-the-art Newark facility with advanced R&D and analytical capabilities to accelerate formulation and production.','Present-tense manufacturer statement; the only printed address is the filed Newark street and the page ties its formulation and production facility to Newark.'),
'SITE-011317':('https://www.minorrubber.com','Our ISO 9001:2015-registered facility in Bloomfield, New Jersey has been producing rubber parts since 1914.','We produce grommets, vibration isolation mounts, extruded profiles, bellows, boots, and bumpers for the most demanding industrial applications.','Bloomfield','Minor Rubber Company 49 Ackerman St Bloomfield, NJ 07003','Compression, transfer, injection, and latex dip molding plus full extrusion capabilities.','Home page places the producing facility in Bloomfield and prints the exact filed street and operator; other-state production is not asserted.'),
'SITE-011456':('https://urethaneusa.com/about/company-history/','Urethane Innovators, Inc., New Bern, NC Our speciality: high-volume, custom urethane parts','Urethane Innovators offers a comprehensive, in-house service package that includes rapid prototyping, tooling, and machining, all of which contribute to the production of top-quality products at competitive prices with short lead times.','New Bern','403 Industrial Drive, New Bern, NC 28562','','Company-history page names the legal operator and New Bern, describes in-house production, and prints the exact filed street.'),
}
def main():
 disc={norm(r['url']):r for f in H.glob('*discovery.json') for r in json.loads(f.read_text())}
 rows=[];(PERSIST/'frozen').mkdir(parents=True,exist_ok=True)
 for sid,(u,q,a,city,bind,ctx,note) in C.items():
  m=disc[norm(u)];assert m['status']=='ok' and same_page(m['final_url'],u),(sid,m['status'])
  text=' '.join((CACHE/m['text_file']).read_text().split());h=hashlib.sha256(text.encode()).hexdigest()
  for name,quote in [('quote',q),('activity',a),('binding',bind),('context',ctx)]:
   if quote:assert on_page(quote,text),('quote not on page',sid,name)
  assert on_page(city,bind)
  (PERSIST/'frozen'/(h+'.txt')).write_text(text)
  rows.append(dict(site_id=sid,source_url=m['final_url'],requested_url=u,quote=q,city_quote=city,binding_quote=bind,note=note,page=str(PERSIST/'frozen'/(h+'.txt')),page_sha256=h,raw_sha256=m['sha256'],fetched_at=m['fetched_at'],source_date='',route=m['route'],activity_quote=a,context_quote=ctx))
 write(H/'selected.csv',rows,list(rows[0]));print(len(rows),'selected')
if __name__=='__main__':main()
